@OptIn(ExperimentalMaterial3AdaptiveApi::class, ExperimentalMonarchApi::class)
NavigableListDetailPaneScaffold(
    navigator = navigator,
    modifier = Modifier.height(MonarchTheme.spacing.space24 * 7),
    listPane = {
        AnimatedPane {
            MonarchAiConversationList(
                conversations = conversations,
                onSelect = ::open,
                activeId = active,
                nowMillis = 1_794_664_800_000L,
                labels = MonarchAiConversationListLabels(search = "Search"),
                onNew = {
                    val id = "c${conversations.size + 1}"
                    conversations = listOf(MonarchAiConversationSummary(id, "", 1_794_664_800_000L)) + conversations
                    open(id)
                },
                onRename = { id, title ->
                    conversations = conversations.map { if (it.id == id) it.copy(title = title) else it }
                },
                onDelete = { id -> conversations = conversations.filterNot { it.id == id } },
            )
        }
    },
    detailPane = {
        AnimatedPane {
            val onePane = navigator.scaffoldValue[ListDetailPaneScaffoldRole.List] == PaneAdaptedValue.Hidden
            Column(modifier = Modifier.fillMaxSize()) {
                MonarchAiConversationHeader(
                    title = conversations.firstOrNull { it.id == active }?.title.orEmpty(),
                    agent = agent,
                    onRename = { title ->
                        conversations = conversations.map { if (it.id == active) it.copy(title = title) else it }
                    },
                    navigationIcon = if (onePane) {
                        {
                            MonarchIconButton(
                                label = "Conversation history",
                                onClick = { scope.launch { navigator.navigateBack() } },
                            ) {
                                MonarchIcon(SampleIcons.ArrowBack, contentDescription = null)
                            }
                        }
                    } else {
                        null
                    },
                    actions = {
                        MonarchButton(
                            text = "Show artifact",
                            onClick = {},
                            variant = MonarchButtonVariant.Secondary,
                            size = MonarchButtonSize.Sm,
                        )
                    },
                )
                MonarchAiThread(
                    messages = messages,
                    modifier = Modifier.weight(1f).padding(horizontal = MonarchTheme.spacing.space4),
                    status = status,
                    error = error,
                    onStop = conversation::stop,
                    empty = {
                        MonarchAiWelcome(
                            title = {{welcome.title}},
                            agent = agent,
                            description = {{welcome.description}},
                            icon = { MonarchIcon(SampleIcons.Bot, contentDescription = null) },
                        ) {
                            MonarchAiStarterPrompts(
                                prompts = listOf(
                                    MonarchAiStarterPrompt({{starters.0.id}}, {{starters.0.title}}, {{starters.0.prompt}}),
                                    MonarchAiStarterPrompt({{starters.1.id}}, {{starters.1.title}}, {{starters.1.prompt}}),
                                ),
                                onSelect = { conversation.send(it.prompt) },
                                layout = MonarchAiStarterPromptsLayout.List,
                            )
                        }
                    },
                )
                MonarchAiPromptInput(
                    label = "Message the assistant",
                    state = prompt,
                    onSubmit = { text -> check(conversation.send(text)) { "Not sent" } },
                    modifier = Modifier.padding(MonarchTheme.spacing.space4),
                    busy = status == MonarchAiConversationStatus.Submitted ||
                        status == MonarchAiConversationStatus.Streaming,
                    onStop = conversation::stop,
                    footer = { MonarchAiDisclaimer() },
                )
            }
        }
    },
)

examples.setupTemplate:
val transport = remember {
    object : MonarchAiTransport {
        override fun stream(request: MonarchAiTransportRequest): Flow<MonarchAiStreamEvent> = flowOf(
            MonarchAiStreamEvent.TextDelta("You asked: " + request.messages.lastOrNull()?.text.orEmpty()),
            MonarchAiStreamEvent.Done(),
        )
    }
}
// One conversation object for the open chat; the app loads stored messages into it with reset.
val conversation = rememberMonarchAiConversation(transport)
val messages by conversation.messages.collectAsState()
val status by conversation.status.collectAsState()
val error by conversation.error.collectAsState()
val agent by conversation.agent.collectAsState()
var conversations by remember {
    mutableStateOf(
        listOf(
            MonarchAiConversationSummary({{conversations.0.id}}, {{conversations.0.title}}, updatedAtMillis = 1_794_660_000_000L),
            MonarchAiConversationSummary({{conversations.1.id}}, {{conversations.1.title}}, updatedAtMillis = 1_794_490_000_000L, pinned = {{conversations.1.pinned}}),
            MonarchAiConversationSummary({{conversations.2.id}}, {{conversations.2.title}}, updatedAtMillis = 1_792_936_800_000L),
        ),
    )
}
var active by rememberSaveable { mutableStateOf({{activeId}}) }
val prompt = rememberTextFieldState()
@OptIn(ExperimentalMaterial3AdaptiveApi::class)
val navigator = rememberListDetailPaneScaffoldNavigator<String>(
    initialDestinationHistory = listOf(ThreePaneScaffoldDestinationItem(ListDetailPaneScaffoldRole.Detail, active)),
)
val scope = rememberCoroutineScope()
@OptIn(ExperimentalMaterial3AdaptiveApi::class)
fun open(id: String) {
    active = id
    conversation.reset(/* The app's stored messages of id. */)
    scope.launch { navigator.navigateTo(ListDetailPaneScaffoldRole.Detail, id) }
}

